using System.Text.Json;

namespace Fineage.Game.Services;

/// <summary>One Mobius respawn point. <see cref="Kind"/> is normal / chaotic / other / banish.</summary>
public sealed record MapRespawnPoint(int X, int Y, int Z, string Kind)
{
    public bool IsChaotic => string.Equals(Kind, "chaotic", StringComparison.OrdinalIgnoreCase);
}

/// <summary>
/// One Mobius <c>MapRegion</c>: a town plus the 32768-unit grid cells it owns
/// (<c>data/map-regions.json</c>, generated by <c>scripts/gen_map_regions.py</c>).
/// </summary>
public sealed record MapRegion(
    string Name,
    string Town,
    int Castle,
    int LocId,
    IReadOnlyList<(int X, int Y)> Maps,
    IReadOnlyList<MapRespawnPoint> RespawnPoints,
    IReadOnlyDictionary<string, string> BannedRace)
{
    public bool Owns(int cellX, int cellY)
    {
        foreach (var (x, y) in Maps)
        {
            if (x == cellX && y == cellY)
                return true;
        }

        return false;
    }

    /// <summary>First non-chaotic respawn point, as Mobius <c>getSpawnLoc()</c> with random respawns off.</summary>
    public MapRespawnPoint? NormalSpawn() => First(p => !p.IsChaotic && p.Kind == "normal");

    /// <summary>
    /// Mobius <c>getSpawnLoc()</c> when <c>RandomRespawnInTownEnabled</c> is on: pick uniformly among
    /// non-chaotic <c>normal</c> points so Scroll of Escape / village restart do not always land on the first row.
    /// </summary>
    public MapRespawnPoint? RandomNormalSpawn(Random? rng = null)
    {
        List<MapRespawnPoint>? normals = null;
        foreach (var p in RespawnPoints)
        {
            if (p.IsChaotic || !string.Equals(p.Kind, "normal", StringComparison.OrdinalIgnoreCase))
                continue;
            (normals ??= []).Add(p);
        }

        if (normals == null || normals.Count == 0)
            return null;
        if (normals.Count == 1)
            return normals[0];
        return normals[(rng ?? Random.Shared).Next(normals.Count)];
    }

    /// <summary>Chaotic (karma) ring; falls back to the town square like Mobius <c>getChaoticSpawnLoc()</c>.</summary>
    public MapRespawnPoint? ChaoticSpawn() => First(p => p.IsChaotic) ?? NormalSpawn();

    MapRespawnPoint? First(Func<MapRespawnPoint, bool> match)
    {
        foreach (var p in RespawnPoints)
        {
            if (match(p))
                return p;
        }

        return null;
    }
}

/// <summary>
/// Mobius <c>MapRegionManager</c>: resolves where "nearest town" is for the Scroll of Escape and a village restart.
/// The cell of a position is <c>(x &gt;&gt; 15) + 20</c>, <c>(y &gt;&gt; 15) + 18</c>; a position outside every region
/// falls back to <c>talking_island_town</c>.
/// </summary>
public sealed class MapRegionCatalog
{
    public const string FileName = "map-regions.json";

    static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        PropertyNameCaseInsensitive = true,
        ReadCommentHandling = JsonCommentHandling.Skip,
        AllowTrailingCommas = true
    };

    readonly Dictionary<(int X, int Y), MapRegion> _byCell;
    readonly Dictionary<string, MapRegion> _byName;

    MapRegionCatalog(Dictionary<(int, int), MapRegion> byCell, Dictionary<string, MapRegion> byName, MapRegion fallback)
    {
        _byCell = byCell;
        _byName = byName;
        Fallback = fallback;
    }

    public static MapRegionCatalog Empty { get; } = new([], [], new MapRegion(
        "talking_island_town", "Talking Island Town", 1, 910, [], [], new Dictionary<string, string>()));

    public MapRegion Fallback { get; }

    public int Count => _byCell.Count;

    /// <summary>Mobius <c>getMapRegionX</c>.</summary>
    public static int CellX(int x) => (x >> 15) + 20;

    /// <summary>Mobius <c>getMapRegionY</c>.</summary>
    public static int CellY(int y) => (y >> 15) + 18;

    public MapRegion? At(int x, int y) =>
        _byCell.TryGetValue((CellX(x), CellY(y)), out var region) ? region : null;

    public MapRegion? ByName(string name) => _byName.TryGetValue(name, out var region) ? region : null;

    /// <summary>
    /// Mobius <c>getTeleToLocation(creature, TOWN)</c> for a character standing at <paramref name="x"/>/<paramref name="y"/>.
    /// Uses a random normal town point (Interlude <c>RandomRespawnInTownEnabled</c>).
    /// </summary>
    public MapRespawnPoint TownRespawn(int x, int y, Random? rng = null) =>
        (At(x, y) ?? Fallback).RandomNormalSpawn(rng)
        ?? (At(x, y) ?? Fallback).NormalSpawn()
        ?? Fallback.RandomNormalSpawn(rng)
        ?? Fallback.NormalSpawn()!;

    public static MapRegionCatalog LoadDefault()
    {
        var path = TeleportCatalog.FindFile(FileName);
        return path == null ? Empty : Parse(File.ReadAllText(path), path);
    }

    public static MapRegionCatalog Parse(string json, string source = FileName)
    {
        FileDto? file;
        try
        {
            file = JsonSerializer.Deserialize<FileDto>(json, JsonOptions);
        }
        catch (JsonException ex)
        {
            throw new InvalidDataException($"{source} is not a map region table.", ex);
        }

        var byCell = new Dictionary<(int, int), MapRegion>();
        var byName = new Dictionary<string, MapRegion>(StringComparer.Ordinal);
        foreach (var row in file?.Regions ?? [])
        {
            if (string.IsNullOrWhiteSpace(row.Name))
                throw new InvalidDataException($"{source} has a region without a name.");
            var cells = (row.Maps ?? []).Select(c => (c[0], c[1])).ToArray();
            var points = (row.RespawnPoints ?? [])
                .Select(p => new MapRespawnPoint(p.X, p.Y, p.Z, p.Kind ?? "normal"))
                .ToArray();
            var banned = (row.BannedRace ?? []).ToDictionary(pair => pair.Key, pair => pair.Value, StringComparer.OrdinalIgnoreCase);
            var region = new MapRegion(row.Name, row.Town ?? row.Name, row.Castle, row.LocId, cells, points, banned);
            byName[row.Name] = region;
            foreach (var cell in cells)
                byCell[cell] = region;
        }

        var fallbackName = file?.DefaultRegion ?? "talking_island_town";
        var fallback = byName.TryGetValue(fallbackName, out var found) ? found : Empty.Fallback;
        return new MapRegionCatalog(byCell, byName, fallback);
    }

    sealed class FileDto
    {
        public string? DefaultRegion { get; set; }
        public List<RegionDto>? Regions { get; set; }
    }

    sealed class RegionDto
    {
        public string? Name { get; set; }
        public string? Town { get; set; }
        public int Castle { get; set; }
        public int LocId { get; set; }
        public List<int[]>? Maps { get; set; }
        public List<PointDto>? RespawnPoints { get; set; }
        public Dictionary<string, string>? BannedRace { get; set; }
    }

    sealed class PointDto
    {
        public int X { get; set; }
        public int Y { get; set; }
        public int Z { get; set; }
        public string? Kind { get; set; }
    }
}
